<div class="admin-page-title"><div><span class="eyebrow">ACERVO</span><h1>Livros</h1><p>Gerencie títulos, preços e quantidade de exemplares.</p></div><a class="btn btn-red" href="<?= h(url('admin/index.php?secao=livro_form')) ?>">+ Cadastrar livro</a></div><div class="admin-card"><div class="table-wrap"><table><thead><tr><th>Título / autor</th><th>Categoria</th><th>Venda</th><th>Aluguel</th><th>Estoque venda</th><th>Exemplares aluguel</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($livros as $l): ?><tr><td><b><?= h($l['titulo']) ?></b><small class="table-sub"><?= h($l['autor']) ?></small></td><td><?= h($l['categoria']) ?></td><td><?= money($l['preco_venda']) ?></td><td><?= money($l['valor_aluguel']) ?></td><td><?= (int)$l['estoque_venda'] ?></td><td><?= (int)$l['estoque_aluguel'] ?></td><td><span class="status <?= $l['ativo']?'ativo':'cancelado' ?>"><?= $l['ativo']?'Ativo':'Oculto' ?></span></td><td class="actions-cell"><a class="link-button" href="<?= h(url('admin/index.php?secao=livro_form&id='.(int)$l['id'])) ?>">Editar</a><?php if($l['ativo']): ?><form method="post" action="<?= h(url('admin/controllers/acao.php')) ?>" onsubmit="return confirm('Ocultar este livro do catálogo?')"><?= csrf_field() ?><input type="hidden" name="acao" value="delete_book"><input type="hidden" name="id" value="<?= (int)$l['id'] ?>"><button class="link-button danger-text">Ocultar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
